<?php
declare(strict_types=1);require_once __DIR__.'/config/lead_step20.php';$error=null;$stage=[];$types=[];$months=[];$sources=[];$m=[];try{$pdo=business_db();$ctx=lead_step20_context($pdo);$orgId=(int)$ctx['organization_id'];$m=lead_step20_metrics($pdo,$orgId);$s=$pdo->prepare("SELECT stage,COUNT(*) total FROM crm_leads WHERE organization_id=? GROUP BY stage ORDER BY total DESC");$s->execute([$orgId]);$stage=$s->fetchAll();$s=$pdo->prepare("SELECT lead_type,COUNT(*) total FROM crm_leads WHERE organization_id=? GROUP BY lead_type ORDER BY total DESC");$s->execute([$orgId]);$types=$s->fetchAll();$s=$pdo->prepare("SELECT DATE_FORMAT(first_seen_at,'%Y-%m') month,COUNT(*) leads,SUM(stage='converted') converted FROM crm_leads WHERE organization_id=? GROUP BY DATE_FORMAT(first_seen_at,'%Y-%m') ORDER BY month DESC LIMIT 18");$s->execute([$orgId]);$months=$s->fetchAll();$s=$pdo->prepare("SELECT COALESCE(src.source_name,'Unknown') source_name,COUNT(*) total FROM crm_leads l LEFT JOIN crm_lead_sources src ON src.id=l.source_id WHERE l.organization_id=? GROUP BY COALESCE(src.source_name,'Unknown') ORDER BY total DESC");$s->execute([$orgId]);$sources=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Lead Analytics</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="lead_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 20 • Lead Analytics</small></span></a><div class="os-top-actions"><a class="os-btn primary" href="lead_center.php">Leads</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">LEAD INTELLIGENCE</div><h1>Understand enquiry volume, conversion and follow-up load without mixing it with sales revenue.</h1><div class="os-status-row"><span class="os-chip good"><?= (int)($m['total']??0) ?> leads</span><span class="os-chip"><?= (int)($m['converted']??0) ?> converted</span><span class="os-chip"><?= (int)($m['overdue_tasks']??0) ?> overdue</span></div></section><?php if($error):?><div class="pp-alert bad"><?= lead_step20_h($error) ?></div><?php endif;?><section class="s10-grid"><article class="s10-card s10-span-6"><h2>By Stage</h2><div class="s10-list"><?php foreach($stage as $r):?><div class="s10-row"><div><b><?= lead_step20_h(ucwords($r['stage'])) ?></b></div><strong><?= (int)$r['total'] ?></strong></div><?php endforeach;?></div></article><article class="s10-card s10-span-6"><h2>By Enquiry Type</h2><div class="s10-list"><?php foreach($types as $r):?><div class="s10-row"><div><b><?= lead_step20_h(ucwords($r['lead_type'])) ?></b></div><strong><?= (int)$r['total'] ?></strong></div><?php endforeach;?></div></article><article class="s10-card s10-span-6"><h2>By Source</h2><div class="s10-list"><?php foreach($sources as $r):?><div class="s10-row"><div><b><?= lead_step20_h($r['source_name']) ?></b></div><strong><?= (int)$r['total'] ?></strong></div><?php endforeach;?></div></article><article class="s10-card s10-span-6"><h2>Monthly Trend</h2><div class="s10-list"><?php foreach($months as $r):?><div class="s10-row"><div><b><?= lead_step20_h($r['month']) ?></b><small><?= (int)$r['converted'] ?> converted</small></div><strong><?= (int)$r['leads'] ?></strong></div><?php endforeach;?></div></article></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
